const {esc,api,toast,modalWide,closeModal}=window;

window.openRankedShortlist=async projectId=>{try{const [d,h]=await Promise.all([api(`/api/v1/projects/${projectId}/ranked-shortlist`),api(`/api/v1/projects/${projectId}/ranked-shortlists`).catch(()=>({publications:[]}))]);const ranked=d.ranked||[],unranked=d.unranked||[];modalWide('证据闭合 Ranked Shortlist',`<p class="subtle">仅对证据已闭合、可比较的候选人排序。缺失/冲突证据保持未排名；此列表不是录用决定，也不使用联系优先级。</p><div class="pill-row"><span class="status good">可比较 ${ranked.length}</span><span class="status warn">未排名 ${unranked.length}</span><span class="status info">协议 ${esc(d.protocol_revision_id||'—')}</span></div><div class="divider"></div><h3>当前排序预览</h3>${ranked.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Rank</th><th>候选人</th><th>岗位匹配</th><th>证据覆盖</th><th>Decision Ready</th><th>阶段</th></tr></thead><tbody>${ranked.map(x=>`<tr><td><strong>#${x.rank}</strong></td><td>${esc(x.display_name)}</td><td><strong>${esc(x.fit_score)}%</strong></td><td>${Math.round(Number(x.evidence_coverage||0)*100)}%</td><td><span class="status ${x.decision_ready?'good':'warn'}">${x.decision_ready?'ready':'仍有业务阻塞'}</span></td><td>${esc(x.pipeline_stage)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">当前没有证据闭合到可以比较的候选人。</div>'}<h3 style="margin-top:16px">未排名</h3>${unranked.length?`<div class="quick-list">${unranked.slice(0,30).map(x=>`<div class="quick-item"><div><div class="quick-title">${esc(x.display_name)}</div><div class="quick-note">${esc(x.reason)} · unresolved ${x.unresolved_keys?.length||0} · conflicts ${x.conflict_keys?.length||0}</div></div><span class="status warn">不计 0 分</span></div>`).join('')}</div>`:'<div class="empty">无未排名候选人</div>'}<h3 style="margin-top:16px">已发布快照</h3>${(h.publications||[]).length?`<div class="quick-list">${h.publications.slice(0,8).map(x=>`<div class="quick-item"><div><div class="quick-title">${new Date(x.created_at).toLocaleString()} · ${esc(x.created_by)}</div><div class="quick-note">ranked ${x.ranked_count} / unranked ${x.unranked_count} · ${esc(x.content_hash.slice(0,12))}</div></div></div>`).join('')}</div>`:'<div class="empty">尚未发布不可变排序快照</div>'}`,`<button class="btn" onclick="closeModal()">关闭</button>${ranked.length?`<button class="btn primary" onclick="publishRankedShortlist('${projectId}')">发布当前排序快照</button>`:''}`)}catch(e){toast(e.message,true)}};
window.publishRankedShortlist=async projectId=>{if(!confirm('发布后会冻结当前协议、材料版本与排序结果，作为可审计快照。确认发布？'))return;try{const r=await api(`/api/v1/projects/${projectId}/ranked-shortlist`,{method:'POST',body:JSON.stringify({actor:'human'})});toast(`短名单快照已发布：${r.publication_id}`);await window.openRankedShortlist(projectId)}catch(e){toast(e.message,true)}};

window.openIdentityMerge=async(reviewId,candidateA,candidateB,targetId)=>{try{targetId=targetId||candidateA;const p=await api(`/api/v1/identity-reviews/${reviewId}/merge-preview?target_candidate_id=${encodeURIComponent(targetId)}`);const counts=p.source_business_history_counts||{};const historyTotal=Object.entries(counts).filter(([k])=>k!=='sources').reduce((a,[,v])=>a+Number(v||0),0);modalWide('Identity Merge Preview',`<p class="subtle">这是显式合并预览。系统只把来源身份的当前材料复制到 canonical candidate；历史面试、判断、Offer 和审计记录不会改写。</p><div class="two"><section class="provider-card"><h3>Canonical / Target</h3><strong>${esc(p.target_candidate.display_name)}</strong><div class="subtle mono">${esc(p.target_candidate.candidate_id)}</div><div class="quick-note">阶段：${esc(p.target_candidate.pipeline_stage)}</div></section><section class="provider-card"><h3>Archive / Source</h3><strong>${esc(p.source_candidate.display_name)}</strong><div class="subtle mono">${esc(p.source_candidate.candidate_id)}</div><div class="quick-note">当前材料 ${p.source_current_source_count} 份 · 保留历史记录 ${historyTotal} 项</div></section></div><div class="divider"></div><div class="quick-list"><div class="quick-item"><span>材料处理</span><strong>${p.effects.copy_source_current_material_to_target?'复制并发布新的 Target Material Revision':'来源没有当前材料，仅建立 canonical identity'}</strong></div><div class="quick-item"><span>联系方式</span><strong>${p.contact_conflicts?.length?`冲突字段保留 Target：${esc(p.contact_conflicts.join(', '))}`:'只填补 Target 空白字段'}</strong></div><div class="quick-item"><span>历史记录</span><strong>不改写，继续留在 Source</strong></div><div class="quick-item"><span>Pipeline</span><strong>不自动改变 Target 阶段</strong></div></div>${p.blocked_reason?`<div class="empty"><strong>不能合并</strong>${esc(p.blocked_reason)}</div>`:''}`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn" onclick="openIdentityMerge('${reviewId}','${candidateA}','${candidateB}','${candidateA}')">以 A 为主</button><button class="btn" onclick="openIdentityMerge('${reviewId}','${candidateA}','${candidateB}','${candidateB}')">以 B 为主</button>${p.can_merge?`<button class="btn primary" onclick="commitIdentityMerge('${reviewId}','${p.target_candidate.candidate_id}')">确认合并</button>`:''}`)}catch(e){toast(e.message,true)}};
window.commitIdentityMerge=async(reviewId,targetId)=>{const note=prompt('合并说明：','已人工确认同一自然人；保留来源身份历史 lineage');if(note===null)return;if(!confirm('确认执行 canonical identity merge？来源候选人会被归档，但历史记录不会删除。'))return;try{const r=await api(`/api/v1/identity-reviews/${reviewId}/merge`,{method:'POST',body:JSON.stringify({target_candidate_id:targetId,actor:'human',note})});window.closeModal?.();toast(`身份合并完成；复制当前材料 ${r.cloned_source_ids?.length||0} 份`);if(window.setProjectTab)await window.setProjectTab('quality')}catch(e){toast(e.message,true)}};

window.openSourceViewer=async(sourceId,page,claimId)=>{try{const d=await api(`/api/v1/sources/${sourceId}/content`);const extractor=d.metadata?.extractor||{};const blocks=extractor.grounding_blocks||[];const targetPage=Number(page||0)||1;let viewer='';if(d.has_blob&&d.media_type==='application/pdf'){if(claimId){const src=`/api/v1/sources/${encodeURIComponent(sourceId)}/page/${targetPage}?claim_id=${encodeURIComponent(claimId)}&scale=1.7`;viewer=`<div style="max-height:68vh;overflow:auto;text-align:center;background:#eee"><img src="${src}" alt="grounded PDF page" style="max-width:100%;height:auto"></div>`}else{viewer=`<iframe title="PDF Source Viewer" src="${d.file_url}#page=${targetPage}" style="width:100%;height:68vh;border:1px solid var(--border);border-radius:8px;background:white"></iframe>`}}else if(d.has_blob&&String(d.media_type||'').startsWith('image/')){viewer=`<div style="max-height:68vh;overflow:auto;text-align:center"><img src="${d.file_url}" alt="source" style="max-width:100%;height:auto"></div>`}else if(d.has_text){viewer=`<div class="codebox" style="white-space:pre-wrap;max-height:68vh;overflow:auto">${esc(d.text_content)}</div>`}else{viewer='<div class="empty">该材料没有可直接预览的文本或受支持二进制文件。</div>'}modalWide(`Source Viewer · ${d.filename||d.source_kind}`,`<div class="pill-row"><span class="status info">${esc(d.media_type)}</span><span class="status">Page ${targetPage}</span><span class="status">Grounding blocks ${blocks.length}</span>${claimId?'<span class="status good">Claim 高亮定位</span>':''}<span class="status ${d.has_blob?'good':'warn'}">${d.has_blob?'原文件可用':'仅文本投影'}</span></div><div style="margin-top:12px">${viewer}</div>`,`<button class="btn" onclick="closeModal()">关闭</button>${claimId&&d.media_type==='application/pdf'?`<button class="btn" onclick="openSourceViewer('${sourceId}','${targetPage}')">打开原生 PDF</button>`:''}${d.has_text?`<button class="btn" onclick="openScoringView('${sourceId}')">隐私评分视图</button>`:''}`)}catch(e){toast(e.message,true)}};
